(() => {
  const modes = [
    {id:'sand',name:'Kinetic sand',short:'Sand',icon:'▰',hint:'Swipe gently to slice',action:'Swipe to slice',detail:'One finger is all you need',count:'cuts',kicker:'TEXTURE STUDIO · 01',color:'#d9a180'},
    {id:'slime',name:'Cloud slime',short:'Slime',icon:'◉',hint:'Pull, stretch & let go',action:'Drag to stretch',detail:'Hold, pull, release',count:'stretches',kicker:'TEXTURE STUDIO · 02',color:'#b9a2d8'},
    {id:'press',name:'Hydraulic press',short:'Press',icon:'▥',hint:'Press and hold to squish',action:'Hold to press',detail:'Watch it slowly give way',count:'presses',kicker:'TEXTURE STUDIO · 03',color:'#8ca8aa'},
    {id:'wash',name:'Power washing',short:'Wash',icon:'⌁',hint:'Swipe away the grime',action:'Swipe to clean',detail:'Reveal the lovely clean tile',count:'cleans',kicker:'TEXTURE STUDIO · 04',color:'#91b5c3'},
    {id:'soap',name:'Soap cutting',short:'Soap',icon:'▱',hint:'Swipe to make a curl',action:'Swipe to shave',detail:'A soft, steady stroke',count:'shaves',kicker:'TEXTURE STUDIO · 05',color:'#e4a8ae'},
    {id:'fruit',name:'Fruit cutting',short:'Fruit',icon:'◒',hint:'Swipe through the fruit',action:'Swipe to slice',detail:'A little slice of calm',count:'slices',kicker:'TEXTURE STUDIO · 06',color:'#e4aa71'}
  ];
  const $ = id => document.getElementById(id);
  const canvas = $('scene'), ctx = canvas.getContext('2d');
  let current = 0, count = 0, progress = 0, slow = false, muted = false, recording = false;
  let pointer = null, lastAction = 0, particles = [], marks = [], cuts = [], toastTimer, audio = null, press = 0, slimePull = null, raf;
  const modeList = $('modeList');

  function buildTabs(){
    modeList.innerHTML = modes.map((m,i)=>`<button class="mode-tab ${i===current?'active':''}" data-mode="${i}" aria-pressed="${i===current}"><span class="mode-emoji">${m.icon}</span>${m.short}</button>`).join('');
    modeList.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>selectMode(+b.dataset.mode)));
  }
  function selectMode(i){
    current=i; count=0; progress=0; particles=[]; marks=[]; cuts=[]; press=0; slimePull=null;
    const m=modes[i];
    buildTabs(); $('sceneTitle').textContent=m.name; $('sceneKicker').textContent=m.kicker; $('hintText').textContent=m.hint;
    $('gestureTitle').textContent=m.action; $('gestureDetail').textContent=m.detail;
    $('gestureIcon').textContent=['↗','↔','↓','⌁','↗','↗'][i]; $('sceneCounter').innerHTML=`0 <span>${m.count}</span>`;
    $('progressValue').textContent='0%'; $('progressBar').style.width='0%';
    draw(); showToast(['Soft as a cloud.','So squishy.','Ready when you are.','A fresh little patch.','Lovely and smooth.','Ripe for a slice.'][i]);
    if(navigator.vibrate){} // intentionally silent haptics by default
  }
  function resize(){
    const r=canvas.getBoundingClientRect(), dpr=Math.min(window.devicePixelRatio||1,2);
    if(!r.width||!r.height)return;
    canvas.width=Math.round(r.width*dpr); canvas.height=Math.round(r.height*dpr);
    ctx.setTransform(dpr,0,0,dpr,0,0); draw();
  }
  function roundRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
  function gradient(x,y,w,h,stops,vertical=true){const g=vertical?ctx.createLinearGradient(x,y,x,y+h):ctx.createLinearGradient(x,y,x+w,y);stops.forEach(([p,c])=>g.addColorStop(p,c));return g}
  function ellipse(x,y,rx,ry,color,blur=0){ctx.save();ctx.filter=blur?`blur(${blur}px)`:'none';ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();ctx.restore()}
  function drawBackground(w,h){
    const m=modes[current], base=ctx.createLinearGradient(0,0,w,h);
    const themes=[['#eee8f2','#e1d8e9','#d6ccdf'],['#e9e3f0','#dcd5e8','#d2cde1'],['#e7eeee','#d9e3e1','#d1dcda'],['#e2eef0','#d2e3e7','#cfdee4'],['#f3e7e7','#edd9de','#e8d0d5'],['#f4eadf','#eee0ce','#ead9c5']][current];
    base.addColorStop(0,themes[0]);base.addColorStop(.58,themes[1]);base.addColorStop(1,themes[2]);ctx.fillStyle=base;ctx.fillRect(0,0,w,h);
    const glow=ctx.createRadialGradient(w*.52,h*.39,8,w*.5,h*.43,w*.65);glow.addColorStop(0,'#ffffff50');glow.addColorStop(1,'#ffffff00');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);
    // Seamless studio sweep and grounding plane
    ctx.fillStyle='#ffffff18';ctx.fillRect(0,h*.72,w,1);
    const floor=ctx.createLinearGradient(0,h*.72,0,h);floor.addColorStop(0,'#ffffff0b');floor.addColorStop(1,'#8e829b10');ctx.fillStyle=floor;ctx.fillRect(0,h*.72,w,h*.28);
    // soft studio-light highlight
    ellipse(w*.77,h*.15,w*.18,h*.065,'#fff6',16);
  }
  function draw(){
    const r=canvas.getBoundingClientRect(), w=r.width,h=r.height;if(!w||!h)return;
    ctx.clearRect(0,0,w,h);drawBackground(w,h);
    const scale=Math.min(w/390,h/300);ctx.save();ctx.translate(w/2,h/2);ctx.scale(scale,scale);ctx.translate(-195,-150);
    if(current===0)drawSand();else if(current===1)drawSlime();else if(current===2)drawPress();else if(current===3)drawWash();else if(current===4)drawSoap();else drawFruit();
    drawParticles();drawMarks();ctx.restore();
  }
  function drawSand(){
    // Sculpted kinetic-sand brick with a visible beveled top and side plane
    const cx=195,cy=170,wd=192,ht=96,depth=28,x=cx-wd/2,y=cy-ht/2;
    ellipse(cx,cy+74,130,19,'#685a6d25',9);
    ctx.beginPath();ctx.moveTo(x,y+15);ctx.quadraticCurveTo(x,y,x+15,y);ctx.lineTo(x+wd-14,y);ctx.quadraticCurveTo(x+wd,y,x+wd,y+14);ctx.lineTo(x+wd,y+ht-10);ctx.lineTo(x+wd+depth,y+ht-25);ctx.lineTo(x+wd+depth,y+depth+4);ctx.lineTo(x+depth,y+depth+17);ctx.lineTo(x+depth,y+ht+depth);ctx.lineTo(x,y+ht);ctx.closePath();
    ctx.fillStyle=gradient(x,y,wd,ht,[[0,'#e7b995'],[.47,'#d7a17e'],[1,'#c68b6f']]);ctx.fill();ctx.strokeStyle='#fff7';ctx.lineWidth=1;ctx.stroke();
    ctx.beginPath();ctx.moveTo(x+depth,y+depth+17);ctx.lineTo(x+wd+depth,y+depth+4);ctx.lineTo(x+wd,y);ctx.lineTo(x,y+15);ctx.closePath();ctx.fillStyle=gradient(x,y,wd,depth,[[0,'#f0c8a4'],[1,'#d9a17f']]);ctx.fill();ctx.strokeStyle='#fff8';ctx.stroke();
    ctx.beginPath();ctx.moveTo(x+wd,y);ctx.lineTo(x+wd+depth,y+4);ctx.lineTo(x+wd+depth,y+ht-25);ctx.lineTo(x+wd,y+ht-10);ctx.closePath();ctx.fillStyle='#b97c68';ctx.fill();
    // fine soft grain
    for(let n=0;n<45;n++){const gx=x+12+(n*47%165),gy=y+18+(n*31%68);ellipse(gx,gy,1.05,.8,n%3?'#fff5':'#986c5916')}
    for(const c of cuts){ctx.save();ctx.translate(c.x-195,c.y-150);ctx.rotate(c.a);ctx.fillStyle='#9f6b58';roundRect(-2,-48,4,96,2);ctx.fill();ctx.restore()}
    // a delicate knife poised at the edge
    ctx.save();ctx.translate(288,87);ctx.rotate(-.43);roundRect(-7,-12,14,50,5);ctx.fillStyle=gradient(0,-12,14,50,[[0,'#fff'],[.45,'#d8dce1'],[1,'#a8adb3']]);ctx.fill();roundRect(-8,26,16,30,6);ctx.fillStyle='#9b829f';ctx.fill();ctx.restore();
  }
  function drawSlime(){
    const cx=195,base=214,stretch=slimePull?Math.min(1.35,Math.abs(slimePull.dx)/100):0;
    ellipse(cx,base+15,126,17,'#66577a23',10);
    // organic glossy dome
    ctx.beginPath();ctx.moveTo(cx-123,base);ctx.bezierCurveTo(cx-116,base-22,cx-82,base-30,cx-66,base-65);ctx.bezierCurveTo(cx-47,base-108,cx+8,base-111,cx+42,base-88);ctx.bezierCurveTo(cx+73,base-67,cx+105,base-47,cx+122,base-3);ctx.quadraticCurveTo(cx+126,base+10,cx+111,base+12);ctx.lineTo(cx-112,base+12);ctx.quadraticCurveTo(cx-128,base+10,cx-123,base);ctx.closePath();
    const grad=ctx.createLinearGradient(cx-55,base-115,cx+42,base+12);grad.addColorStop(0,'#f7d8f6');grad.addColorStop(.32,'#d4b8ec');grad.addColorStop(.72,'#b499d5');grad.addColorStop(1,'#a283c3');ctx.fillStyle=grad;ctx.fill();ctx.strokeStyle='#ffffff85';ctx.lineWidth=2;ctx.stroke();
    // highlight ribbons
    ctx.beginPath();ctx.ellipse(cx-36,base-72,30,9,-.7,0,Math.PI*2);ctx.fillStyle='#fff9';ctx.fill();
    ctx.beginPath();ctx.ellipse(cx+38,base-38,17,5,-.4,0,Math.PI*2);ctx.fillStyle='#fff6';ctx.fill();
    for(let i=0;i<5;i++){const bx=cx-52+i*26,by=base-18-(i%2)*12;ctx.beginPath();ctx.arc(bx,by,3+i%3,0,Math.PI*2);ctx.fillStyle='#f8eaff65';ctx.fill();ctx.strokeStyle='#fff7';ctx.lineWidth=1;ctx.stroke()}
    if(slimePull){const x=195+slimePull.dx*.65;ctx.beginPath();ctx.moveTo(244,145);ctx.quadraticCurveTo(250,108,x,95);ctx.quadraticCurveTo(x+10,127,254,157);ctx.fillStyle='#c2a8e1c9';ctx.fill();ctx.strokeStyle='#fff8';ctx.stroke()}
    for(let i=0;i<5;i++){const bx=cx-85+i*39,by=base-9-Math.sin(i*1.7)*5;ctx.beginPath();ctx.arc(bx,by,2.4,0,Math.PI*2);ctx.fillStyle='#fff8';ctx.fill()}
  }
  function drawPress(){
    ellipse(195,245,130,15,'#52656822',9);
    // machine body
    ctx.fillStyle='#718d8f';roundRect(86,45,222,21,8);ctx.fill();ctx.fillStyle='#8fa9a9';roundRect(99,55,196,151,7);ctx.fill();
    ctx.fillStyle='#d5e0dc';roundRect(113,64,168,123,4);ctx.fill();ctx.fillStyle='#b5c9c6';roundRect(121,69,152,112,3);ctx.fill();
    // column sides and top cap
    ctx.fillStyle='#698587';roundRect(95,55,20,167,5);ctx.fill();roundRect(279,55,20,167,5);ctx.fill();
    ctx.fillStyle='#dce7e4';roundRect(81,39,232,18,8);ctx.fill();ctx.fillStyle='#fff9';roundRect(92,43,209,4,2);ctx.fill();
    // piston with progressive travel
    const py=103+press*34;ctx.fillStyle='#768f90';roundRect(176,65,38,py-65,4);ctx.fill();ctx.fillStyle='#9eb3b1';roundRect(146,py-7,98,17,4);ctx.fill();ctx.fillStyle='#d7e3df';roundRect(151,py-5,88,5,2);ctx.fill();
    // deforming soft object
    const squash=press;ctx.beginPath();ctx.moveTo(139,209);ctx.bezierCurveTo(130,192-squash*25,145,185-squash*29,166,190-squash*25);ctx.bezierCurveTo(185,171-squash*8,210,177-squash*12,224,190-squash*18);ctx.bezierCurveTo(240,185-squash*20,253,195-squash*12,251,209);ctx.closePath();ctx.fillStyle=gradient(145,178,100,35,[[0,'#e8b3a5'],[1,'#bf7e79']]);ctx.fill();ctx.strokeStyle='#fce5d8';ctx.lineWidth=2;ctx.stroke();
    for(let i=0;i<6;i++){ctx.beginPath();ctx.arc(153+i*18,199-squash*18,2,0,Math.PI*2);ctx.fillStyle='#fff9';ctx.fill()}
    // controls
    ellipse(289,79,4,4,'#e8c994');ellipse(289,92,4,4,'#d48d83');
  }
  function drawWash(){
    // tiled dirty wall with progressive clean reveal
    const x=48,y=45,w=294,h=190;ctx.save();roundRect(x,y,w,h,8);ctx.clip();ctx.fillStyle='#9a8f83';ctx.fillRect(x,y,w,h);
    for(let row=0;row<4;row++)for(let col=0;col<4;col++){
      const tx=x+col*74+(row%2)*0,ty=y+row*48;const clean=marks.some(m=>Math.hypot(tx+36-m.x,ty+22-m.y)<m.r+38);
      ctx.fillStyle=clean?gradient(tx,ty,74,48,[[0,'#eef5f1'],[1,'#cfdfdc']]):gradient(tx,ty,74,48,[[0,'#b8ab9d'],[1,'#a29487']]);ctx.fillRect(tx+1,ty+1,72,46);
      if(!clean){for(let j=0;j<7;j++)ellipse(tx+8+(j*19)%58,ty+7+(j*13)%31,3+(j%3),2+(j%2),'#655a5130')}
      ctx.strokeStyle='#ffffff80';ctx.lineWidth=2;ctx.strokeRect(tx+1,ty+1,72,46);
    }
    ctx.restore();ctx.strokeStyle='#fff9';ctx.lineWidth=2;roundRect(x,y,w,h,8);ctx.stroke();
    // nozzle and glimmer
    ctx.save();ctx.translate(280,204);ctx.rotate(.55);roundRect(-7,-22,14,43,5);ctx.fillStyle='#e6eceb';ctx.fill();roundRect(-10,-32,20,15,4);ctx.fillStyle='#84999d';ctx.fill();ctx.restore();
    if(pointer){ctx.strokeStyle='#dffaffb0';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(280,199);ctx.lineTo(pointer.x,pointer.y);ctx.stroke()}
    for(let i=0;i<14;i++){const bx=48+(i*79)%286,by=50+(i*47)%180;ellipse(bx,by,1.1,1.8,'#fff8')}
  }

function drawSoap(){
  const cx=194,cy=168;ellipse(cx,cy+74,126,17,'#77545620',10);
  // soap bar perspective with soft corners
  ctx.save();ctx.translate(cx,cy);ctx.rotate(-.07);
  ctx.beginPath();ctx.moveTo(-109,-44);ctx.quadraticCurveTo(-109,-57,-94,-60);ctx.lineTo(86,-65);ctx.quadraticCurveTo(105,-64,108,-48);ctx.lineTo(110,40);ctx.quadraticCurveTo(108,53,92,55);ctx.lineTo(-93,60);ctx.quadraticCurveTo(-110,59,-110,43);ctx.closePath();
  ctx.fillStyle=gradient(-110,-65,220,125,[[0,'#f8c7c8'],[.4,'#eaa5ad'],[1,'#ce808e']]);ctx.fill();ctx.strokeStyle='#fff9';ctx.lineWidth=2;ctx.stroke();
  ctx.beginPath();ctx.ellipse(-4,-2,53,23,-.04,0,Math.PI*2);ctx.strokeStyle='#f9d6d5aa';ctx.lineWidth=2;ctx.stroke();ctx.beginPath();ctx.ellipse(-4,-2,44,17,0,0,Math.PI*2);ctx.strokeStyle='#c7778390';ctx.lineWidth=1;ctx.stroke();
  ctx.beginPath();ctx.ellipse(-52,-35,31,9,-.15,0,Math.PI*2);ctx.fillStyle='#fff5';ctx.fill();ctx.restore();
  // curling shavings
  cuts.forEach((c,i)=>{ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.a);ctx.beginPath();ctx.moveTo(-25,0);ctx.quadraticCurveTo(-8,-15,6,0);ctx.quadraticCurveTo(20,14,30,-1);ctx.strokeStyle='#f8c6c9';ctx.lineWidth=4;ctx.lineCap='round';ctx.stroke();ctx.restore()});
  ctx.save();ctx.translate(288,95);ctx.rotate(-.35);roundRect(-5,-5,10,47,4);ctx.fillStyle='#dce0e2';ctx.fill();ctx.restore();
}
function drawFruit(){
  const cx=195,cy=161;ellipse(cx,cy+86,130,18,'#855a3b20',9);
  // fruit as an orange with dimpled skin and leaf
  const grad=ctx.createRadialGradient(cx-38,cy-43,6,cx,cy,106);grad.addColorStop(0,'#ffe0a2');grad.addColorStop(.38,'#f6b765');grad.addColorStop(.82,'#e78843');grad.addColorStop(1,'#c96b38');
  ctx.beginPath();ctx.moveTo(cx,cy-88);ctx.bezierCurveTo(cx+61,cy-89,cx+91,cy-44,cx+85,cy+19);ctx.bezierCurveTo(cx+79,cy+70,cx+43,cy+90,cx,cy+83);ctx.bezierCurveTo(cx-47,cy+90,cx-82,cy+60,cx-86,cy+10);ctx.bezierCurveTo(cx-91,cy-41,cx-61,cy-87,cx,cy-88);ctx.fillStyle=grad;ctx.fill();ctx.strokeStyle='#fff8';ctx.lineWidth=2;ctx.stroke();
  // rind pores
  for(let i=0;i<42;i++){const a=i*2.399,r=24+(i*19%57),px=cx+Math.cos(a)*r,py=cy+Math.sin(a)*r*.9;ellipse(px,py,1.3,1.3,i%2?'#fff5':'#a9512935')}
  ctx.beginPath();ctx.moveTo(cx-3,cy-76);ctx.quadraticCurveTo(cx+12,cy-102,cx+42,cy-94);ctx.quadraticCurveTo(cx+26,cy-72,cx-3,cy-76);ctx.fillStyle='#79956d';ctx.fill();ctx.strokeStyle='#eff3d4';ctx.stroke();
  cuts.forEach(c=>{ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.a);ctx.beginPath();ctx.ellipse(0,0,42,18,0,0,Math.PI*2);ctx.fillStyle='#ffdc96';ctx.fill();ctx.strokeStyle='#fff6d8';ctx.lineWidth=4;ctx.stroke();for(let j=0;j<5;j++)ellipse(-23+j*11,Math.sin(j*2)*7,2,3,'#9b6239');ctx.restore()});
  ctx.beginPath();ctx.ellipse(cx-41,cy-40,25,11,-.65,0,Math.PI*2);ctx.fillStyle='#fff5';ctx.fill();
}
function drawParticles(){
  for(const p of particles){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.ellipse(p.x,p.y,p.size,p.size*(p.oval||1),p.rot||0,0,Math.PI*2);ctx.fill()};ctx.globalAlpha=1;
}
function drawMarks(){
  if(current===3){for(const m of marks){const g=ctx.createRadialGradient(m.x,m.y,2,m.x,m.y,m.r);g.addColorStop(0,'#e9f8f6dd');g.addColorStop(.7,'#d7efedaa');g.addColorStop(1,'#d7efed00');ctx.fillStyle=g;ctx.beginPath();ctx.arc(m.x,m.y,m.r,0,Math.PI*2);ctx.fill()}}
  cuts.forEach(c=>{if(current===0){ctx.strokeStyle='#9c6f5c99';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(c.x-75,c.y-45);ctx.lineTo(c.x+65,c.y+42);ctx.stroke()}})
}
function addParticles(x,y,n=15,color){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=1+Math.random()*2.2;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-1,life:.65+Math.random()*.45,size:1+Math.random()*2,color:color||modes[current].color,oval:.6+Math.random()})}}
function tick(){
  for(const p of particles){p.x+=p.vx;p.y+=p.vy;p.vy+=.035;p.vx*=.985;p.life-=.012}
  particles=particles.filter(p=>p.life>0);
  if(press>0&&!pointer){press=Math.max(0,press-.018)}
  if(slimePull&& !pointer){slimePull.dx*=.84;if(Math.abs(slimePull.dx)<1)slimePull=null}
  if(particles.length||press>0||slimePull)draw();
  raf=requestAnimationFrame(tick);
}
function coords(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*390/r.width,y:(e.clientY-r.top)*300/r.height}}
function start(e){e.preventDefault();canvas.setPointerCapture(e.pointerId);pointer={...coords(e),sx:coords(e).x,sy:coords(e).y};if(current===2)press=.14;if(current===1)slimePull={dx:0};draw()}
function move(e){if(!pointer)return;e.preventDefault();const p=coords(e),dx=p.x-pointer.sx,dy=p.y-pointer.sy;pointer={...p,sx:pointer.sx,sy:pointer.sy};if(current===1)slimePull={dx};if(current===2)press=Math.min(1,press+.018);if(current===3){marks.push({x:p.x,y:p.y,r:31});if(Math.random()<.25)addParticles(p.x,p.y,2,'#e6fbff')};draw()}
function end(e){if(!pointer)return;const p=coords(e),dx=p.x-pointer.sx,dy=p.y-pointer.sy,dist=Math.hypot(dx,dy);const mode=current;pointer=null;
  if(mode===2){press=Math.min(1,press+.18);commitAction(press>.65?'A lovely little crush.':'Nice and slow.',p.x,p.y);if(press>.55)addParticles(p.x,p.y,20,'#e4b7a4');return}
  if(mode===3){if(dist>6){marks.push({x:p.x,y:p.y,r:55+Math.min(dist,45)});addParticles(p.x,p.y,13,'#e9fbff');commitAction('Look at that clean patch.',p.x,p.y,'water')}return}
  if(dist>12){if(mode===1){slimePull={dx:Math.max(-110,Math.min(110,dx))};addParticles(p.x,p.y,12,'#e4d8f6')}else{cuts.push({x:p.x,y:p.y,a:Math.atan2(dy,dx)});addParticles(p.x,p.y,mode===4?8:16,mode===4?'#f4cbd0':null)}commitAction(['','That stretch!','', '', 'A perfect little curl.','A juicy slice.'][mode],p.x,p.y,mode===0?'sand':mode===4?'texture':mode===5?'impact':'texture')}
  else if(mode===1){addParticles(p.x,p.y,9,'#f7e7ff');commitAction('A little pop.',p.x,p.y,'impact')}
  else {addParticles(p.x,p.y,5);commitAction('A gentle tap.',p.x,p.y,'texture')}
}

