  function sound(kind='texture'){
    if(muted)return;try{
      if(!audio)audio=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();
      const now=audio.currentTime,master=audio.createGain();master.gain.value=(volumes[kind]??.65)*.32;master.connect(audio.destination);
      const n=audio.createBuffer(1,Math.floor(audio.sampleRate*.32),audio.sampleRate),d=n.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/d.length,2);
      const src=audio.createBufferSource();src.buffer=n;const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=kind==='water'?1500:kind==='impact'?1000:650;const g=audio.createGain();g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(.7,now+.025);g.gain.exponentialRampToValueAtTime(.0001,now+.26);src.connect(filter);filter.connect(g);g.connect(master);src.start(now);src.stop(now+.3);
      const osc=audio.createOscillator(),og=audio.createGain();osc.type='sine';osc.frequency.setValueAtTime(kind==='impact'?175:kind==='water'?430:240,now);osc.frequency.exponentialRampToValueAtTime(kind==='impact'?80:kind==='water'?180:120,now+.16);og.gain.setValueAtTime(.0001,now);og.gain.exponentialRampToValueAtTime(.15,now+.012);og.gain.exponentialRampToValueAtTime(.0001,now+.2);osc.connect(og);og.connect(master);osc.start(now);osc.stop(now+.22);
    }catch(_){/* Audio is an enhancement; interaction stays available if unavailable. */}
  }
  let volumes={texture:.7,impact:.52,water:.58};
  function commitAction(message,x,y,category='texture'){
    count++;progress=Math.min(100,Math.round(progress+Math.max(4,100/12)));lastAction=performance.now();
    const m=modes[current];$('sceneCounter').innerHTML=`${count} <span>${m.count}</span>`;$('progressValue').textContent=`${progress}%`;$('progressBar').style.width=`${progress}%`;
    if(message)showToast(message);sound(category);$('hint').style.opacity='.18';setTimeout(()=>{$('hint').style.opacity=''},850);draw();
    if(progress>=100){setTimeout(()=>showToast('A whole little world, made by you.'),500);}
  }
  function showToast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1350)}
  function reset(){count=0;progress=0;cuts=[];marks=[];particles=[];press=0;slimePull=null;$('sceneCounter').innerHTML=`0 <span>${modes[current].count}</span>`;$('progressValue').textContent='0%';$('progressBar').style.width='0%';draw();showToast('A fresh start.')}
  function replay(){
    const old=count;if(!old){showToast('Your canvas is ready.');return}
    particles=[];for(let i=0;i<Math.min(16,old*2);i++)addParticles(125+Math.random()*140,95+Math.random()*100,1);
    if(current===2)press=.7;if(current===1)slimePull={dx:63};
    draw();sound(current===3?'water':'texture');showToast('One more time, nice and slow.');
  }
  function setSlow(value){slow=value;$('slowButton').classList.toggle('active',slow);$('slowButton').setAttribute('aria-pressed',String(slow));$('slowChip').classList.toggle('visible',slow);canvas.style.filter=slow?'saturate(.88)':'none';if(slow)showToast('Take your time.');}
  canvas.addEventListener('pointerdown',start);canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);
  $('resetButton').addEventListener('click',reset);$('replayButton').addEventListener('click',replay);$('slowButton').addEventListener('click',()=>setSlow(!slow));
  $('soundToggle').addEventListener('click',()=>{muted=!muted;$('soundToggle').classList.toggle('muted',muted);$('soundIcon').textContent=muted?'×':'◖))';$('soundToggle').title=muted?'Sound off':'Sound on';$('soundToggle').setAttribute('aria-label',muted?'Unmute sounds':'Mute sounds');if(!muted)sound('texture')});
  $('recordToggle').addEventListener('click',()=>{recording=!recording;document.body.classList.toggle('recording',recording);$('recordToggle').classList.toggle('active',recording);showToast(recording?'Recording view is ready.':'Back to the studio.')});
  $('mixToggle').addEventListener('click',()=>{const open=$('mixControls').classList.toggle('open');$('mixToggle').setAttribute('aria-expanded',String(open));$('mixToggle').innerHTML=open?'MIX <span>−</span>':'MIX <span>＋</span>'});
  document.querySelectorAll('[data-volume]').forEach(input=>input.addEventListener('input',()=>{volumes[input.dataset.volume]=input.value/100}));
  window.addEventListener('resize',resize,{passive:true});window.addEventListener('orientationchange',()=>setTimeout(resize,100));
  buildTabs();resize();tick();
