function sand(){let cx=195,cy=170,W=192,H=96,D=28,x=cx-W/2,y=cy-H/2;ellipse(cx,cy+74,130,19,'#685a6d25',9);ctx.beginPath();ctx.moveTo(x,y+15);ctx.quadraticCurveTo(x,y,x+15,y);ctx.lineTo(x+W-14,y);ctx.quadraticCurveTo(x+W,y,x+W,y+14);ctx.lineTo(x+W,y+H-10);ctx.lineTo(x+W+D,y+H-25);ctx.lineTo(x+W+D,y+D+4);ctx.lineTo(x+D,y+D+17);ctx.lineTo(x+D,y+H+D);ctx.lineTo(x,y+H);ctx.closePath();ctx.fillStyle=grad(x,y,W,H,[[0,'#e7b995'],[.47,'#d7a17e'],[1,'#c68b6f']]);ctx.fill();ctx.strokeStyle='#fff7';ctx.stroke();ctx.beginPath();ctx.moveTo(x+D,y+D+17);ctx.lineTo(x+W+D,y+D+4);ctx.lineTo(x+W,y);ctx.lineTo(x,y+15);ctx.closePath();ctx.fillStyle=grad(x,y,W,D,[[0,'#f0c8a4'],[1,'#d9a17f']]);ctx.fill();ctx.strokeStyle='#fff8';ctx.stroke();ctx.fillStyle='#b97c68';ctx.beginPath();ctx.moveTo(x+W,y);ctx.lineTo(x+W+D,y+4);ctx.lineTo(x+W+D,y+H-25);ctx.lineTo(x+W,y+H-10);ctx.fill();for(let n=0;n<45;n++)ellipse(x+12+n*47%165,y+18+n*31%68,1,.8,n%3?'#fff5':'#986c5916');for(let c of cuts){ctx.strokeStyle='#9c6f5c99';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(c.x-75,c.y-45);ctx.lineTo(c.x+65,c.y+42);ctx.stroke()}ctx.save();ctx.translate(288,87);ctx.rotate(-.43);rr(-7,-12,14,50,5);ctx.fillStyle=grad(0,-12,14,50,[[0,'#fff'],[.45,'#d8dce1'],[1,'#a8adb3']]);ctx.fill();rr(-8,26,16,30,6);ctx.fillStyle='#9b829f';ctx.fill();ctx.restore()}
